import type { Metadata } from 'next';
import { SITE_URL, canonicalUrl } from '@/lib/site';
import {
  DESC_MAX,
  DESC_MIN,
  ROOT_TITLE,
  SITE_NAME,
  TITLE_BRAND,
  TITLE_MAX,
  TOPIC_MAX,
} from './constants';

// Single source for page metadata. No page writes a
// raw `metadata` object except console layouts (use CONSOLE_ROBOTS).
//
// Title: "{Topic} — Crowsnest", <= 60 characters, via `title.absolute` so the
// root layout needs NO title.template (delete the old "%s · Crowsnest").

/** Sitewide card, generated by app/opengraph-image.tsx. */
export const DEFAULT_OG_IMAGE_PATH = '/opengraph-image';

export type OgType = 'website' | 'article';

export interface BuildMetadataInput {
  /** Site path, e.g. "/docs/coral-engine". */
  path: string;
  /** Topic only; the brand is appended. Pass `null` for the landing page. */
  title: string | null;
  description: string;
  type?: OgType;
  /** ISO dates. Only emitted for type "article". */
  publishedTime?: string;
  modifiedTime?: string;
  authors?: string[];
  /** `articleSection`, emitted as article:section. */
  section?: string;
  /**
   * Explicit OG/Twitter image URL (absolute or site path). Omit when the
   * segment has an opengraph-image file: Next adds the tags itself.
   */
  ogImage?: string;
  /** Alt text for `ogImage`; defaults to the full title. */
  ogImageAlt?: string;
  /** True when the page has a `.md` twin: adds <link rel="alternate" type="text/markdown">. */
  markdown?: boolean;
}

/** Truncate a topic on a word boundary to at most `max` characters. No ellipsis. */
export function truncateTopic(topic: string, max: number = TOPIC_MAX): string {
  const t = topic.trim().replace(/\s+/g, ' ');
  if (t.length <= max) return t;
  const cut = t.slice(0, max + 1);
  const space = cut.lastIndexOf(' ');
  const base = space > 0 ? cut.slice(0, space) : t.slice(0, max);
  return base.replace(/[\s,;:.\-—–]+$/, '');
}

/** Full <title> string. Landing (`null` topic) uses ROOT_TITLE. */
export function formatTitle(topic: string | null): string {
  return topic === null ? ROOT_TITLE : `${truncateTopic(topic)}${TITLE_BRAND}`;
}

export interface MetadataProblem {
  field: 'title' | 'description' | 'path';
  message: string;
}

/**
 * Contract check used by the vitest suite (and callable in a build script).
 * `buildMetadata` truncates the title to stay valid; this function FAILS
 * instead, so authors shorten the source (`metaTitle`) rather than ship a
 * silently clipped title.
 */
export function checkMetadataInput(input: Pick<BuildMetadataInput, 'path' | 'title' | 'description'>): MetadataProblem[] {
  const problems: MetadataProblem[] = [];
  if (input.title !== null) {
    if (input.title.length > TOPIC_MAX) {
      problems.push({
        field: 'title',
        message: `topic is ${input.title.length} characters, max ${TOPIC_MAX} (title would exceed ${TITLE_MAX}); provide a shorter metaTitle`,
      });
    }
    if (input.title.endsWith(TITLE_BRAND.trim()) || input.title.includes('· Crowsnest')) {
      problems.push({ field: 'title', message: 'topic must not include the brand suffix' });
    }
  }
  const d = input.description.length;
  if (d < DESC_MIN || d > DESC_MAX) {
    problems.push({ field: 'description', message: `description is ${d} characters, must be ${DESC_MIN}-${DESC_MAX}` });
  }
  if (/\.\.\.|…$/.test(input.description)) {
    problems.push({ field: 'description', message: 'description must not end with an ellipsis' });
  }
  if (!input.path.startsWith('/') || /[?#]/.test(input.path) || /\.md$/.test(input.path)) {
    problems.push({ field: 'path', message: 'path must start with "/" and have no query, hash or .md suffix' });
  }
  return problems;
}

export const PUBLIC_ROBOTS: NonNullable<Metadata['robots']> = {
  index: true,
  follow: true,
  googleBot: {
    index: true,
    follow: true,
    'max-snippet': -1,
    'max-image-preview': 'large',
    'max-video-preview': -1,
  },
};

/** For console segment layouts (owned by the console) and not-found. */
export const CONSOLE_ROBOTS: NonNullable<Metadata['robots']> = {
  index: false,
  follow: false,
  googleBot: { index: false, follow: false },
};

export function buildMetadata(input: BuildMetadataInput): Metadata {
  const title = formatTitle(input.title);
  const canonical = canonicalUrl(input.path);
  const type: OgType = input.type ?? 'website';
  // Every page carries og:image and twitter:image. Per-page openGraph replaces
  // the root opengraph-image file's tags, so the helper emits them itself and
  // falls back to the sitewide card (app/opengraph-image.tsx).
  const imageUrl = input.ogImage ?? canonicalUrl(DEFAULT_OG_IMAGE_PATH);
  const images = [{ url: imageUrl, width: 1200, height: 630, alt: input.ogImageAlt ?? title }];

  const openGraph: NonNullable<Metadata['openGraph']> =
    type === 'article'
      ? {
          type: 'article',
          title,
          description: input.description,
          url: canonical,
          siteName: SITE_NAME,
          locale: 'en_US',
          ...(input.publishedTime ? { publishedTime: input.publishedTime } : {}),
          ...(input.modifiedTime ? { modifiedTime: input.modifiedTime } : {}),
          ...(input.authors?.length ? { authors: input.authors } : {}),
          ...(input.section ? { section: input.section } : {}),
          images,
        }
      : {
          type: 'website',
          title,
          description: input.description,
          url: canonical,
          siteName: SITE_NAME,
          locale: 'en_US',
          images,
        };

  return {
    title: { absolute: title },
    description: input.description,
    alternates: {
      canonical,
      ...(input.markdown ? { types: { 'text/markdown': `${SITE_URL}${input.path}.md` } } : {}),
    },
    robots: PUBLIC_ROBOTS,
    openGraph,
    twitter: {
      card: 'summary_large_image',
      title,
      description: input.description,
      images: [imageUrl],
    },
    ...(input.authors?.length ? { authors: input.authors.map((name) => ({ name })) } : {}),
    ...(input.section ? { other: { 'article:section': input.section } } : {}),
  };
}

/**
 * Metadata for the ROOT layout only. No title.template (pages supply absolute
 * titles), no keywords, RSS alternate, formatDetection off.
 */
export function rootMetadata(description: string): Metadata {
  return {
    metadataBase: new URL(SITE_URL),
    title: ROOT_TITLE,
    description,
    alternates: { types: { 'application/rss+xml': '/rss.xml' } },
    robots: PUBLIC_ROBOTS,
    formatDetection: { email: false, address: false, telephone: false },
    openGraph: { siteName: SITE_NAME, locale: 'en_US', type: 'website' },
  };
}
